def top_k_frequent(nums, k):
    counts = {}
    for n in nums:
        if n < 0:
            continue
        counts[n] = counts.get(n, 0) + 1
    return [n for n, _ in sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:k]]
